-- À exécuter après create_db.sql, voyages.sql et catalogue_enrichi.sql.
-- 1. Rend le catalogue bilingue (titres et descriptions en anglais, langue des demandes de devis).
-- 2. Élargit le catalogue à 36 destinations (données de démonstration : prix, durées et places sont fictifs).
--    Les voyages existants sont mis à jour (traductions, dates de départ, corrections de pays et de catégories)
--    et les nouvelles destinations sont ajoutées, avec des photos libres de droits (voir CREDITS.md).
SET NAMES utf8mb4;
USE latitudes;

ALTER TABLE voyages
    ADD COLUMN titre_en VARCHAR(255) NULL AFTER titre,
    ADD COLUMN description_en TEXT NULL AFTER description;

-- Langue dans laquelle le visiteur a envoyé sa demande (pour lui répondre dans la même langue)
ALTER TABLE demandes
    ADD COLUMN langue CHAR(2) NOT NULL DEFAULT 'fr' AFTER message;

INSERT INTO voyages
    (id, titre, titre_en, continent, pays, date_depart, categorie, description, description_en,
     prix, duree_jours, places_disponibles, id_utilisateur, image)
VALUES
    (16, 'Plages d’Ibiza', 'Ibiza’s Beaches', 'Europe', 'Espagne', '2027-08-10', 'Plage',
     'Vivez l’alliance parfaite entre farniente, eaux turquoise et ambiance festive dans l’une des destinations balnéaires les plus emblématiques de la Méditerranée.',
     'Enjoy the perfect blend of laziness, turquoise waters and festive spirit on one of the most iconic beach destinations of the Mediterranean.',
