     '["uploads/68616dd780b5c_france2.jpg","uploads/68616dd780cef_france3.jpg"]'),
    (18, 'Safari au Serengeti', 'Serengeti Safari', 'Afrique', 'Tanzanie', '2027-07-05', 'Safari',
