     '["uploads/68616dc4399e1_tanzanie1.jpg","uploads/68616dc439a3d_tanzanie2.jpg","uploads/68616dc439a87_tanzanie3.jpg","uploads/68616dc439aca_tanzanie4.jpg"]'),
    (19, 'Tokyo by night', 'Tokyo by Night', 'Asie', 'Japon', '2027-10-01', 'Culture',
