     '["uploads/68616ce0608ba_suisse1.jpg","uploads/68616ce060933_suisse2.jpg","uploads/68616ce060990_suisse3.jpg"]'),
    (24, 'Road trip en Californie', 'California Road Trip', 'Amérique', 'États-Unis', '2027-08-22', 'Nature',
