     '["uploads/68616cbcd372e_Brésil1.jpg","uploads/68616cbcd377c_Brésil2.jpg","uploads/68616cbcd37bf_Brésil3.jpg"]'),
    (26, 'Coucher de soleil à Santorin', 'Sunset in Santorini', 'Europe', 'Grèce', '2027-09-10', 'Île tropicale',
